head.script:
// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};



scwin.onpageload = function () {
    // 정적 select1 selectedIndex 초기값 보정 (init 미적용 대비)
    par_rowIndex.setValue("0");
    par_columnInfo.setValue("1");
    par_dataType.setValue("number");

    dlt_bind.setJSON([
        { "col1": "", "col2": "", "col3": "", "col4": "" },        
    ]);
};



// ===== custom Column typeGetter =====
// col1(custom) : Cell inputType=text     -> 가이드 허용 4종, 실제 동작
scwin.target1_textTypeGetter = function (info) {
    return { id: 'cell_text_' + info.rowIndex + '_' + info.colIndex, inputType: 'text', options: { textAlign: 'right' } };
};

// col2(custom) : Cell inputType=textarea -> 가이드 허용 4종, 엔진 결함으로 미동작
scwin.target1_textareaTypeGetter = function (info) {
    return { id: 'cell_textarea_' + info.rowIndex + '_' + info.colIndex, inputType: 'textarea', options: {} };
};

// col3(custom) : Cell inputType=input    -> 가이드 허용 4종, 엔진 결함으로 미동작
scwin.target1_inputTypeGetter = function (info) {
    return { id: 'cell_input_' + info.rowIndex + '_' + info.colIndex, inputType: 'input', options: {} };
};

// col4(custom) : Cell inputType=secret   -> 가이드 허용 4종, 실제 동작
scwin.target1_secretTypeGetter = function (info) {
    return { id: 'cell_secret_' + info.rowIndex + '_' + info.colIndex, inputType: 'secret', options: {} };
};



// 해당 Cell 의 dataType 속성값을 조회 (custom 컬럼은 Cell 단위 cellManager.options.dataType)
scwin.getCellDataType = function (rowIndex, columnInfo) {
    var api = target1;
    var colIndex = api.getColumnIndex(columnInfo);
    var cellInfo = api.getCellInfo(colIndex);
    if (cellInfo && cellInfo.options && cellInfo.options.inputType === "custom") {
        var realRow = api.dataList.getRealRowIndex(rowIndex);
        var cm = cellInfo.cellManagerHashByRowIndex ? cellInfo.cellManagerHashByRowIndex[realRow] : null;
        return cm && cm.options ? "(Cell) " + cm.options.dataType : "(Cell 미생성)";
    }
    return cellInfo && cellInfo.options ? "(Column) " + cellInfo.options.dataType : "(미확인)";
};



// [재현 버튼] 선택한 Cell 에 setCellDataType('number') 호출
scwin.btn_setCellDataType_onclick = function () {
    var rowIndex = Number(par_rowIndex.getValue());
    var columnInfo = Number(par_columnInfo.getValue());
    var dataType = par_dataType.getValue();

    var beforeType = scwin.getCellDataType(rowIndex, columnInfo);

    var ret;
    try {
        ret = target1.setCellDataType(rowIndex, columnInfo, dataType);
    } catch (ex) {
        ret = "throw: " + ex.message;
    }

    var afterType = scwin.getCellDataType(rowIndex, columnInfo);
    var changed = (beforeType !== afterType);

    scwin.setReturnValue(
        "setCellDataType(" + rowIndex + ", " + columnInfo + ", '" + dataType + "') | 변경 전 : " + beforeType +
        " -> 변경 후 : " + afterType + " | 변경됨 : " + changed +
        (changed ? "" : "  <== 미동작(결함). 콘솔의 TypeError 가 try/catch 에 먹혀 조용히 무시됨"));
};
